/**
 * The Earth at the end of the galaxy journey: a globe centered on Amman, lit for the moment the
 * page was opened, so Amman is on its real side of the line between night and day.
 *
 * Painted into a sprite, a band of rows per frame (`step`), so it never stalls the sky. First from
 * the drawn map (src/data/earth.json, generated by scripts/make-earth-map.mjs: land and sea, colored
 * by latitude); then, once the photographs have arrived (`loadEarthPhotos`, owner's request,
 * 2026-11-13), painted again from them: NASA's Blue Marble by day and its Earth at Night (2012) on
 * the night side, both public domain (src/assets/earth, see the README's credits). The new picture replaces the old one only when it is complete, and if
 * the photographs never arrive, the drawn map stays.
 */
import map from '../../data/earth.json';
import { AMMAN, RAD, subsolarPoint } from './astro';

type Canvas = OffscreenCanvas | HTMLCanvasElement;
type Ctx = OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D;

const W = map.width;
const H = map.height;
let land: Uint8Array | undefined;

function decode() {
  const out = new Uint8Array(W * H);
  map.rows.forEach((row, r) => {
    let col = 0;
    let value = 0;
    for (const run of row.split('.')) {
      const n = parseInt(run, 36);
      if (value) out.fill(1, r * W + col, r * W + col + n);
      col += n;
      value ^= 1;
    }
  });
  return out;
}

/** How much of the ground at a latitude and longitude (degrees) is land, blended between cells. */
function landAt(lat: number, lon: number) {
  const m = (land ??= decode());
  const fx = ((lon + 180) / 360) * W - 0.5;
  const fy = ((90 - lat) / 180) * H - 0.5;
  const x0 = Math.floor(fx);
  const y0 = Math.max(0, Math.min(H - 2, Math.floor(fy)));
  const tx = fx - x0;
  const ty = Math.max(0, Math.min(1, fy - y0));
  const at = (x: number, y: number) => m[y * W + (((x % W) + W) % W)];
  const top = at(x0, y0) * (1 - tx) + at(x0 + 1, y0) * tx;
  const bottom = at(x0, y0 + 1) * (1 - tx) + at(x0 + 1, y0 + 1) * tx;
  return top * (1 - ty) + bottom * ty;
}

/**
 * The Earth photographed, equirectangular RGBA: by day, and by night (moonlit land with its city
 * lights, already in their colors).
 */
export interface EarthPhotos {
  width: number;
  height: number;
  day: Uint8ClampedArray;
  night: Uint8ClampedArray;
}

/** Fetch and decode the photographs (in the worker), or null if anything fails. */
export async function loadEarthPhotos(dayUrl: string, nightUrl: string): Promise<EarthPhotos | null> {
  try {
    const [day, night] = await Promise.all(
      [dayUrl, nightUrl].map(async (url) => {
        const r = await fetch(url);
        if (!r.ok) throw new Error(String(r.status));
        return createImageBitmap(await r.blob());
      }),
    );
    const { width, height } = day;
    const read = (bitmap: ImageBitmap) => {
      const c = new OffscreenCanvas(width, height);
      const g = c.getContext('2d')!;
      g.drawImage(bitmap, 0, 0, width, height);
      bitmap.close();
      return g.getImageData(0, 0, width, height).data;
    };
    return { width, height, day: read(day), night: read(night) };
  } catch {
    return null;
  }
}

/** Bilinear sample of a photograph at a latitude and longitude (degrees): channel `c` of `stride`. */
function sample(data: Uint8ClampedArray, W: number, H: number, stride: number, c: number, lat: number, lon: number) {
  const fx = ((lon + 180) / 360) * W - 0.5;
  const fy = Math.max(0, Math.min(H - 1.001, ((90 - lat) / 180) * H - 0.5));
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const at = (x: number, y: number) => data[(y * W + (((x % W) + W) % W)) * stride + c];
  const top = at(x0, y0) * (1 - tx) + at(x0 + 1, y0) * tx;
  const bottom = at(x0, y0 + 1) * (1 - tx) + at(x0 + 1, y0 + 1) * tx;
  return top * (1 - ty) + bottom * ty;
}

const OCEAN = [24, 60, 112];
const DESERT = [150, 128, 94];
const GREEN = [84, 100, 70];
const ICE = [206, 214, 224];
const NIGHT_OCEAN = [3, 6, 14];
const NIGHT_LAND = [11, 14, 26];
const DAWN = [255, 146, 86];
/** How bright the night picture is drawn: a little under its own, so the night side stays night. */
const NIGHT_GAIN = 0.9;
/** How much the city lights are brightened, and their color (sodium and LED light from orbit). */
const LIGHTS_BOOST = 1.6;
const CITY = [1, 0.78, 0.5];

const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

export function createGlobe(size: number, at: number, makeCanvas: (w: number, h: number) => Canvas) {
  const canvas = makeCanvas(size, size);
  const ctx = canvas.getContext('2d') as Ctx;
  const image = ctx.createImageData(size, size);
  const px = image.data;
  const R = size / 2;

  // The view: looking straight down at Amman, north up
  const p0 = AMMAN.lat * RAD;
  const l0 = AMMAN.lon * RAD;
  const f = [Math.cos(p0) * Math.cos(l0), Math.cos(p0) * Math.sin(l0), Math.sin(p0)];
  const e = [-Math.sin(l0), Math.cos(l0), 0];
  const n = [-Math.sin(p0) * Math.cos(l0), -Math.sin(p0) * Math.sin(l0), Math.cos(p0)];
  const sub = subsolarPoint(at);
  const S = [Math.cos(sub.lat) * Math.cos(sub.lon), Math.cos(sub.lat) * Math.sin(sub.lon), Math.sin(sub.lat)];

  let row = 0;
  let painted = false;
  let photos: EarthPhotos | null = null;
  return {
    canvas,
    /** The direction of the Sun as seen on the globe, in screen radians (y down). */
    sunAngle: Math.atan2(-(S[0] * n[0] + S[1] * n[1] + S[2] * n[2]), S[0] * e[0] + S[1] * e[1] + S[2] * e[2]),
    /** A complete picture is on the canvas (it stays there while a new one is painted). */
    get done() {
      return painted;
    },
    /** Rows are still being painted. */
    get busy() {
      return row < size;
    },
    /** Paint the globe again from the photographs; the drawn map shows until they are complete. */
    usePhotos(p: EarthPhotos) {
      photos = p;
      row = 0;
    },
    /**
     * Paint the next rows; returns true once the globe is complete. Fewer at a time from the
     * photographs, whose pixels cost more (Safari took about 25 ms for 48 of their rows, 8 for 14).
     */
    step(rows = photos ? 10 : 48) {
      if (row >= size) return true;
      const end = Math.min(size, row + rows);
      for (; row < end; row++) {
        const y = 1 - (row + 0.5) / R;
        for (let col = 0; col < size; col++) {
          const x = (col + 0.5) / R - 1;
          const r2 = x * x + y * y;
          const i = (row * size + col) * 4;
          // Soft edge, one pixel wide
          const edge = Math.min(1, Math.max(0, (1 - Math.sqrt(r2)) * R + 0.5));
          if (edge <= 0) {
            px[i + 3] = 0;
            continue;
          }
          const z = Math.sqrt(Math.max(0, 1 - r2));
          const X = x * e[0] + y * n[0] + z * f[0];
          const Y = x * e[1] + y * n[1] + z * f[1];
          const Z = x * e[2] + y * n[2] + z * f[2];
          const lat = Math.asin(Math.max(-1, Math.min(1, Z))) / RAD;
          const lon = Math.atan2(Y, X) / RAD;
          const mu = X * S[0] + Y * S[1] + Z * S[2];
          const limb = 0.72 + 0.28 * z;
          // A faint warm wash where dawn is breaking, fading into the night side
          const glow = 0.09 * Math.exp(-(((mu + 0.01) / 0.05) ** 2));
          const day = smooth(-0.05, 0.08, mu);
          if (photos) {
            // The photographs: the day picture, darkening toward the line between night and day,
            // and the night picture beyond it
            const light = 0.3 + 0.7 * smooth(-0.02, 0.4, mu);
            // City lights are warm and the moonlit land is blue, so warmth picks out the lights,
            // which the resized picture has dimmed; they get brightened back
            const { night, width: PW, height: PH } = photos;
            const warmth = Math.max(0, sample(night, PW, PH, 4, 0, lat, lon) - sample(night, PW, PH, 4, 2, lat, lon));
            for (let c = 0; c < 3; c++) {
              const surface = sample(photos.day, PW, PH, 4, c, lat, lon);
              const dark = NIGHT_GAIN * sample(night, PW, PH, 4, c, lat, lon) + LIGHTS_BOOST * warmth * CITY[c];
              px[i + c] = (dark + (surface * light - dark) * day + DAWN[c] * glow) * limb;
            }
            px[i + 3] = 255 * edge;
            continue;
          }
          const ground = landAt(lat, lon);
          // Dry land toward the tropics, greener farther out, ice only near the poles; blended, so
          // there are no bands
          const a = Math.abs(lat);
          const green = smooth(28, 46, a);
          const ice = smooth(68, 76, a);
          const light = 0.45 + 0.55 * smooth(0, 0.5, mu);
          for (let c = 0; c < 3; c++) {
            const terrain = (DESERT[c] * (1 - green) + GREEN[c] * green) * (1 - ice) + ICE[c] * ice;
            const lit = (OCEAN[c] * (1 - ground) + terrain * ground) * light;
            const dark = NIGHT_OCEAN[c] * (1 - ground) + NIGHT_LAND[c] * ground;
            px[i + c] = (dark + (lit - dark) * day + DAWN[c] * glow) * limb;
          }
          px[i + 3] = 255 * edge;
        }
      }
      if (row >= size) {
        ctx.putImageData(image, 0, 0);
        painted = true;
      }
      return row >= size;
    },
  };
}
